using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using MediaBrowser.Model.Tasks;
namespace XtreamBridge;
[ApiController,Route("XtreamBridge/Manage"),Authorize(Policy="RequiresElevation")]
public sealed class ManagementController(LiveEngine live,GuideEngine guide,Playback playback,SyncService sync,SyncQueue queue,ITaskManager tasks):ControllerBase
{
 [HttpGet("Settings")] public IActionResult Settings()=>Ok(ConfigurationService.Redacted(Panel.Config));
 [HttpPost("Settings")] public IActionResult Save([FromBody] Settings settings){try{ConfigurationService.Save(settings);return Ok(new{Message="Settings saved. Sync to apply changes to Jellyfin."});}catch(PanelException e){return BadRequest(new{Message=e.Message});}}
 [HttpPost("Sync")] public IActionResult Sync([FromQuery] bool approveRemovals=false)=>queue.Enqueue(approveRemovals)?Accepted(new{Message="Sync queued"}):Conflict(new{Message="A sync is already queued."});
 [HttpGet("Status")] public IActionResult Status()=>Ok(new{Version=typeof(Plugin).Assembly.GetName().Version?.ToString(),Sync=sync.State,Providers=live.Status,GuideWarnings=guide.Errors.Values,NativeDvr=Panel.Config.NativeDvr,Tasks=tasks.ScheduledTasks.Where(t=>t.ScheduledTask.Key=="RefreshGuide"||t.ScheduledTask.Key=="XtreamLiveSync").Select(t=>new{t.ScheduledTask.Name,t.State})});
 [HttpGet("Channels")] public async Task<IActionResult> Channels(CancellationToken ct){var all=await live.Inventory(ct,false);var visible=(await live.Inventory(ct)).ToDictionary(e=>e.Id);return Ok(all.Select(e=>new{Original=e,Effective=visible.GetValueOrDefault(e.Id),Enabled=visible.ContainsKey(e.Id),Rule=Panel.Config.ChannelRules.FirstOrDefault(r=>r.Id==e.Id)}));}
 [HttpGet("Coverage")]public async Task<IActionResult> Coverage(CancellationToken ct)=>Ok(await guide.Coverage(ct));
 [HttpGet("EpgIds")]public async Task<IActionResult> EpgIds([FromQuery]string provider="primary",[FromQuery]bool alternative=false,CancellationToken ct=default){try{return Ok(await guide.EpgIds(provider,alternative,ct));}catch(Exception e) when(e is ArgumentException or InvalidOperationException or UriFormatException){return BadRequest(new{Message="Select a configured provider and guide source."});}}
 [HttpPost("Probe")]public async Task<IActionResult> Probe([FromQuery]string id,CancellationToken ct){try{return Ok(await playback.Probe(id,ct));}catch(PanelException e){return BadRequest(new{Message=e.Message});}}
 [HttpPost("Test")]public async Task<IActionResult> Test([FromQuery]string provider="primary",CancellationToken ct=default){try{var p=Providers.All(Panel.Config).FirstOrDefault(p=>p.Id==provider);if(p.Config==null)return BadRequest(new{Message="Provider is not configured."});var data=await Panel.Api(p.Config,"",ct,fresh:true);if(!data.TryGetProperty("user_info",out var u))return BadRequest(new{Message="Unexpected account response."});return Ok(new{Success=Panel.S(u,"auth")=="1",Status=Panel.S(u,"status"),Expires=Panel.S(u,"exp_date"),ActiveConnections=Panel.S(u,"active_cons"),ConnectionLimit=Panel.S(u,"max_connections")});}catch(PanelException e){return BadRequest(new{Message=e.Message});}}
 [HttpGet("Export")]public IActionResult Export()=>Ok(new RuleExport{Channels=Panel.Config.ChannelRules,Categories=Panel.Config.CategoryRules});
 [HttpPost("Import")]public IActionResult Import([FromBody]RuleExport rules){if(rules.Schema!=1)return BadRequest(new{Message="Unsupported export schema."});try{var c=System.Text.Json.JsonSerializer.Deserialize<Settings>(System.Text.Json.JsonSerializer.Serialize(Panel.Config))!;c.ChannelRules=rules.Channels;c.CategoryRules=rules.Categories;ConfigurationService.Validate(c);Plugin.Instance.UpdateConfiguration(c);return Ok(new{Message="Channel and category rules imported. Connection credentials were not changed."});}catch(PanelException e){return BadRequest(new{Message=e.Message});}}
 [HttpGet("Support")]public async Task<IActionResult> Support(CancellationToken ct){var items=await live.Inventory(ct);return Ok(new{PluginVersion=typeof(Plugin).Assembly.GetName().Version?.ToString(),Generated=DateTime.UtcNow,VisibleChannels=items.Count,Groups=items.Select(x=>x.Group).Distinct().Count(),MissingEpgIds=items.Count(x=>x.EpgId.Length==0),Providers=live.Status.Select(s=>new{s.State,s.Imported,s.Added,s.Removed,s.Renamed,s.LastSuccess}),Sync=new{sync.State.Stage,sync.State.LastComplete},GuideWarningCount=guide.Errors.Count,Note="No provider URLs, usernames, passwords, channel titles or raw logs are included."});}
}
